// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;

    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 ether, 1000 ether);
        Attacker attacker = new Attacker();
        attacker.setTarget(address(c));
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.deposit{value: amount}();

        bool ok;
        vm.prank(address(attacker));
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        assertTrue(ok && address(c).balance == 0);
    }
}

contract Attacker {
    ReentrancyDAO target;
    bool reentered;

    function setTarget(address t) external { target = ReentrancyDAO(t); }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            target.withdrawAll();
        }
    }
}
